preflight.run:
$ErrorActionPreference = "Stop"
# apps/ inside sdkwork-agents is the separate sdkwork-agents-apps repository,
# recorded in the parent tree as a submodule whose URL is SSH
# (git@github.com:sdkwork-ai/sdkwork-agents-apps.git). The packaging dependency
# checkout clones over HTTPS and cannot initialize an SSH submodule, so the PC
# workspace would lose the twelve agents packages it depends on
# (ERR_PNPM_WORKSPACE_PKG_NOT_FOUND). Materialize the exact revision the parent
# pins, over HTTPS, keeping the token out of any clone URL.
$agentsApps = "../sdkwork-agents/apps"
$pinned = "d2c31ab3e44c66b0c9a4f301783fb17a6e8db69e"
$marker = Join-Path $agentsApps "sdkwork-agents-pc/package.json"
if (Test-Path $marker) {
  Write-Host "[cloudrouter-preflight] $agentsApps already materialized"
} else {
  Write-Host "[cloudrouter-preflight] materializing $agentsApps at $pinned"
  New-Item -ItemType Directory -Force -Path $agentsApps | Out-Null
  if (-not (Test-Path (Join-Path $agentsApps ".git"))) { git -C $agentsApps init --quiet }
  git -C $agentsApps remote get-url origin *> $null
  if ($LASTEXITCODE -ne 0) { git -C $agentsApps remote add origin https://github.com/sdkwork-ai/sdkwork-agents-apps.git }
  $basic = [Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("x-access-token:$env:GH_TOKEN"))
  git -c "http.https://github.com/.extraheader=AUTHORIZATION: basic $basic" -C $agentsApps fetch --depth 1 origin $pinned
  if ($LASTEXITCODE -ne 0) { throw "failed to fetch sdkwork-agents-apps at $pinned (exit $LASTEXITCODE)" }
  git -C $agentsApps checkout --detach FETCH_HEAD
  if ($LASTEXITCODE -ne 0) { throw "failed to check out sdkwork-agents-apps at $pinned (exit $LASTEXITCODE)" }
}

build.run:
$ErrorActionPreference = "Stop"
$downloadArgs = @("--version", $env:SDKWORK_PACKAGE_VERSION, "--release-tag", $env:SDKWORK_RELEASE_TAG)
if ($env:CLOUDROUTER_DOWNLOAD_CDN_BASE_URL) {
  $downloadArgs += @("--cdn-base-url", $env:CLOUDROUTER_DOWNLOAD_CDN_BASE_URL)
}
# Every command is checked: a bare native command does not stop a PowerShell
# step, so a failed build would otherwise be masked by the next successful
# command and surface later as a confusing missing-artifact error.
node scripts/update-cloud-router-downloads.mjs @downloadArgs
if ($LASTEXITCODE -ne 0) { throw "download catalog generation failed (exit $LASTEXITCODE)" }
node scripts/build-cloud-router-production.mjs
if ($LASTEXITCODE -ne 0) { throw "production build failed (exit $LASTEXITCODE)" }
cargo build -p sdkwork-cloudrouter-installer --bin cloudrouterctl --release
if ($LASTEXITCODE -ne 0) { throw "cloudrouterctl build failed (exit $LASTEXITCODE)" }
# The container image bakes one portal dist tree per deployment profile
# (DEPLOYMENT_SPEC.md section 5): the standalone build above covers the
# single-container unit, the cloud lane needs its own dist/cloud/<alias> tree.
if ($env:SDKWORK_DEPLOYMENT_PROFILE -eq "cloud") {
  pnpm --dir apps/sdkwork-cloudrouter-pc build:prod:cloud
  if ($LASTEXITCODE -ne 0) { throw "cloud portal build failed (exit $LASTEXITCODE)" }
}

package.run:
$ErrorActionPreference = "Stop"
function Resolve-CloudRouterPackageId([string] $packageId) {
  switch ($packageId) {
    "linux-debian-x64-standalone-server-deb" { return "linux-x64-service" }
    "linux-debian-arm64-standalone-server-deb" { return "linux-arm64-service" }
    "linux-x64-standalone-server-tar-gz" { return "linux-x64-archive" }
    "linux-arm64-standalone-server-tar-gz" { return "linux-arm64-archive" }
    "windows-x64-standalone-server-msi" { return "windows-x64-service" }
    "windows-arm64-standalone-server-msi" { return "windows-arm64-service" }
    "windows-x64-standalone-server-zip" { return "windows-x64-archive" }
    "windows-arm64-standalone-server-zip" { return "windows-arm64-archive" }
    "macos-x64-standalone-server-pkg" { return "macos-x64-service" }
    "macos-arm64-standalone-server-pkg" { return "macos-arm64-service" }
    "macos-x64-standalone-server-tar-gz" { return "macos-x64-archive" }
    "macos-arm64-standalone-server-tar-gz" { return "macos-arm64-archive" }
    "linux-debian-x64-standalone-desktop-deb" { return "linux-x64-desktop" }
    "linux-debian-arm64-standalone-desktop-deb" { return "linux-arm64-desktop" }
    "windows-x64-standalone-desktop-msi" { return "windows-x64-desktop" }
    "windows-arm64-standalone-desktop-msi" { return "windows-arm64-desktop" }
    "macos-x64-standalone-desktop-pkg" { return "macos-x64-desktop" }
    "macos-arm64-standalone-desktop-pkg" { return "macos-arm64-desktop" }
    "container-x64-standalone-container-oci" { return "linux-x64-container" }
    "container-arm64-standalone-container-oci" { return "linux-arm64-container" }
    default { throw "Unsupported SDKWork package id $packageId" }
  }
}
$legacyPackageId = Resolve-CloudRouterPackageId $env:SDKWORK_PACKAGE_ID
if ($env:SDKWORK_PACKAGE_FORMAT -in @("deb", "pkg", "msi")) {
  node scripts/build-cloud-router-native-installer.mjs --package-id $legacyPackageId --version $env:SDKWORK_PACKAGE_VERSION --staging-root dist/install-package-staging --output-dir dist/install-packages --json
} else {
  node scripts/build-cloud-router-install-package.mjs --package-id $legacyPackageId --version $env:SDKWORK_PACKAGE_VERSION --staging-root dist/install-package-staging --output-dir dist/install-packages --json
}

$ErrorActionPreference = "Stop"
if ($env:SDKWORK_PACKAGE_FORMAT -ne "oci") {
  Write-Host "[container-image] skipped: package format '$($env:SDKWORK_PACKAGE_FORMAT)' is not oci"
} else {
  $containerImage = (Get-Content -Raw sdkwork.app.config.json | ConvertFrom-Json).app.identifiers.containerImage
  if (-not $containerImage) { throw "sdkwork.app.config.json app.identifiers.containerImage is required for container publication" }
  $deploymentProfile = $env:SDKWORK_DEPLOYMENT_PROFILE
  # Tag convention: the single-container (standalone) image keeps the bare
  # release tag that every compose file, bin/ entrypoint, and the app manifest
  # reference; the cloud image/orchestration bundle adds the deployment-profile
  # segment. This is a profile token, never an environment token.
  $imageTag = if ($deploymentProfile -eq "standalone") {
    "{0}:{1}" -f $containerImage, $env:SDKWORK_PACKAGE_VERSION
  } else {
    "{0}:{1}-{2}" -f $containerImage, $env:SDKWORK_PACKAGE_VERSION, $deploymentProfile
  }
  $containerPackageId = switch ($env:SDKWORK_PACKAGE_TARGET_ID) {
    "container-x64-standalone-container-oci" { "linux-x64-container" }
    "container-arm64-standalone-container-oci" { "linux-arm64-container" }
    "container-x64-cloud-container-oci" { "linux-x64-container" }
    "container-arm64-cloud-container-oci" { "linux-arm64-container" }
    default { throw "Unsupported container package target $env:SDKWORK_PACKAGE_TARGET_ID" }
  }
  node scripts/build-cloud-router-container.mjs --package-id $containerPackageId --version $env:SDKWORK_PACKAGE_VERSION --deployment-profile $deploymentProfile --tag $imageTag --push
  if ($LASTEXITCODE -ne 0) { throw "container image publication failed (exit $LASTEXITCODE) for $imageTag" }
}

validate.run:
$ErrorActionPreference = "Stop"
function Resolve-CloudRouterPackageId([string] $packageId) {
  switch ($packageId) {
    "linux-debian-x64-standalone-server-deb" { return "linux-x64-service" }
    "linux-debian-arm64-standalone-server-deb" { return "linux-arm64-service" }
    "linux-x64-standalone-server-tar-gz" { return "linux-x64-archive" }
    "linux-arm64-standalone-server-tar-gz" { return "linux-arm64-archive" }
    "windows-x64-standalone-server-msi" { return "windows-x64-service" }
    "windows-arm64-standalone-server-msi" { return "windows-arm64-service" }
    "windows-x64-standalone-server-zip" { return "windows-x64-archive" }
    "windows-arm64-standalone-server-zip" { return "windows-arm64-archive" }
    "macos-x64-standalone-server-pkg" { return "macos-x64-service" }
    "macos-arm64-standalone-server-pkg" { return "macos-arm64-service" }
    "macos-x64-standalone-server-tar-gz" { return "macos-x64-archive" }
    "macos-arm64-standalone-server-tar-gz" { return "macos-arm64-archive" }
    "linux-debian-x64-standalone-desktop-deb" { return "linux-x64-desktop" }
    "linux-debian-arm64-standalone-desktop-deb" { return "linux-arm64-desktop" }
    "windows-x64-standalone-desktop-msi" { return "windows-x64-desktop" }
    "windows-arm64-standalone-desktop-msi" { return "windows-arm64-desktop" }
    "macos-x64-standalone-desktop-pkg" { return "macos-x64-desktop" }
    "macos-arm64-standalone-desktop-pkg" { return "macos-arm64-desktop" }
    "container-x64-standalone-container-oci" { return "linux-x64-container" }
    "container-arm64-standalone-container-oci" { return "linux-arm64-container" }
    default { throw "Unsupported SDKWork package id $packageId" }
  }
}
function Resolve-CloudRouterArtifactId([string] $legacyPackageId) {
  $parts = $legacyPackageId -split "-"
  if ($parts.Length -ne 3) { throw "Invalid legacy Cloud Router package id $legacyPackageId" }
  if ($parts[2] -eq "service") { return "$($parts[0])-$($parts[1])-server" }
  return $legacyPackageId
}
$legacyPackageId = Resolve-CloudRouterPackageId $env:SDKWORK_PACKAGE_ID
$legacyArtifactId = Resolve-CloudRouterArtifactId $legacyPackageId
$formatExt = if ($env:SDKWORK_PACKAGE_FORMAT -eq "oci") { "tar.gz" } else { $env:SDKWORK_PACKAGE_FORMAT }
$pattern = "cloudrouter-$legacyArtifactId-$env:SDKWORK_PACKAGE_VERSION.$formatExt"
$file = Get-ChildItem -Path "dist/install-packages" -File |
  Where-Object { $_.Name -like $pattern -and $_.Name -notlike "*.manifest.json" -and $_.Name -notlike "install-packages-manifest*.json" } |
  Select-Object -First 1
if (-not $file) { throw "Missing built install package artifact matching $pattern for $env:SDKWORK_PACKAGE_ID" }
node scripts/validate-cloud-router-install-artifacts.mjs --package-id $legacyPackageId --artifact-path $file.FullName --version $env:SDKWORK_PACKAGE_VERSION

$ErrorActionPreference = "Stop"
if ($env:SDKWORK_PACKAGE_FORMAT -ne "oci") {
  Write-Host "[container-image] manifest validation skipped: package format '$($env:SDKWORK_PACKAGE_FORMAT)' is not oci"
} else {
  $containerPackageId = switch ($env:SDKWORK_PACKAGE_TARGET_ID) {
    "container-x64-standalone-container-oci" { "linux-x64-container" }
    "container-arm64-standalone-container-oci" { "linux-arm64-container" }
    "container-x64-cloud-container-oci" { "linux-x64-container" }
    "container-arm64-cloud-container-oci" { "linux-arm64-container" }
    default { throw "Unsupported container package target $env:SDKWORK_PACKAGE_TARGET_ID" }
  }
  node scripts/build-cloud-router-container.mjs --validate-manifest --require-repo-digest --package-id $containerPackageId --deployment-profile $env:SDKWORK_DEPLOYMENT_PROFILE --version $env:SDKWORK_PACKAGE_VERSION
  if ($LASTEXITCODE -ne 0) { throw "container image manifest validation failed (exit $LASTEXITCODE)" }
}

sign.run:
$ErrorActionPreference = "Stop"
$packageId = $env:SDKWORK_PACKAGE_ID
$variant = $env:SDKWORK_PACKAGE_VARIANT
$artifactsDir = "./deployments/artifacts"
if (-not (Test-Path $artifactsDir)) { New-Item -ItemType Directory -Path $artifactsDir -Force | Out-Null }

# 1. Cosign (OCI images + generic artifacts) — requires COSIGN_PRIVATE_KEY / COSIGN_PASSWORD / COSIGN_PUBLIC_KEY
if ($env:COSIGN_PRIVATE_KEY -and $env:SDKWORK_SIGNING_ENABLED -eq "true") {
  Write-Host "[sign] cosign available; signing artifacts in $artifactsDir"
  $sbomPath = Join-Path $artifactsDir "sbom.spdx.json"
  if (Test-Path $sbomPath) {
    cosign attach sbom --type spdxjson $sbomPath
    cosign sign-blob --yes --output-certificate (Join-Path $artifactsDir "sbom.spdx.json.pem") --output-signature (Join-Path $artifactsDir "sbom.spdx.json.sig") $sbomPath
    Write-Host "[sign] cosign signed SBOM: $sbomPath"
  }
  $checksumsPath = Join-Path $artifactsDir "checksums.json"
  if (Test-Path $checksumsPath) {
    cosign sign-blob --yes --output-certificate (Join-Path $artifactsDir "checksums.json.pem") --output-signature (Join-Path $artifactsDir "checksums.json.sig") $checksumsPath
    Write-Host "[sign] cosign signed checksums: $checksumsPath"
  }
} else {
  Write-Host "[sign] cosign skipped (COSIGN_PRIVATE_KEY or SDKWORK_SIGNING_ENABLED not set) for $packageId ($variant)"
}

# 2. Windows MSI — signtool (requires SDKWORK_SIGNTOOL_PATH + SDKWORK_CERT_PFX_PATH + SDKWORK_CERT_PASSWORD)
if ($variant -eq "windows-msi" -and $env:SDKWORK_CERT_PFX_PATH -and $env:SDKWORK_CERT_PASSWORD) {
  $signtool = if ($env:SDKWORK_SIGNTOOL_PATH) { $env:SDKWORK_SIGNTOOL_PATH } else { "signtool.exe" }
  $msiFiles = Get-ChildItem -Path "./dist/install-packages" -Filter "*.msi" -ErrorAction SilentlyContinue
  foreach ($msi in $msiFiles) {
    & $signtool sign /f $env:SDKWORK_CERT_PFX_PATH /p $env:SDKWORK_CERT_PASSWORD /fd SHA256 /td SHA256 /tr http://timestamp.digicert.com $msi.FullName
    if ($LASTEXITCODE -ne 0) { throw "signtool failed for $($msi.FullName) (exit $LASTEXITCODE)" }
    Write-Host "[sign] signtool signed MSI: $($msi.FullName)"
  }
} else {
  Write-Host "[sign] signtool skipped (not windows-msi variant or missing SDKWORK_CERT_PFX_PATH)"
}

# 3. macOS pkg — codesign + notarytool (requires SDKWORK_APPLE_DEVELOPER_ID + SDKWORK_APPLE_APP_SPECIFIC_PASSWORD + SDKWORK_APPLE_TEAM_ID + SDKWORK_APPLE_KEYCHAIN_PROFILE)
if ($variant -eq "macos-pkg" -and $env:SDKWORK_APPLE_DEVELOPER_ID -and $env:SDKWORK_APPLE_APP_SPECIFIC_PASSWORD) {
  $pkgFiles = Get-ChildItem -Path "./dist/install-packages" -Filter "*.pkg" -ErrorAction SilentlyContinue
  foreach ($pkg in $pkgFiles) {
    & codesign --force --sign $env:SDKWORK_APPLE_DEVELOPER_ID --timestamp $pkg.FullName
    if ($LASTEXITCODE -ne 0) { throw "codesign failed for $($pkg.FullName) (exit $LASTEXITCODE)" }
    & xcrun notarytool submit $pkg.FullName --apple-id $env:SDKWORK_APPLE_DEVELOPER_ID --password $env:SDKWORK_APPLE_APP_SPECIFIC_PASSWORD --team-id $env:SDKWORK_APPLE_TEAM_ID --wait
    & xcrun stapler staple $pkg.FullName
    if ($LASTEXITCODE -ne 0) { throw "stapler failed for $($pkg.FullName) (exit $LASTEXITCODE)" }
    Write-Host "[sign] codesign+notarytool signed pkg: $($pkg.FullName)"
  }
} else {
  Write-Host "[sign] codesign skipped (not macos-pkg variant or missing SDKWORK_APPLE_DEVELOPER_ID)"
}

Write-Host "[sign] signing pipeline complete for $packageId ($variant)"
